exercises.prompt:
The TMDB popular movies endpoint returns objects with a vote_average field. You define:
interface Movie { id: number; title: string; voteAverage: number }

You cast the response as Movie[]. What is the problem?

exercises.code:
interface Movie { id: number; title: string; vote_average: number; poster_path: string }

async function fetchPopularMovies(apiKey: string) {
  const res = await fetch(`https://api.themoviedb.org/3/movie/popular?api_key=${apiKey}`)
  // check res.ok and throw if not
  // parse and return as Movie[]
}

exercises.answer:
interface Movie { id: number; title: string; vote_average: number; poster_path: string }

async function fetchPopularMovies(apiKey: string): Promise<Movie[]> {
  const res = await fetch(`https://api.themoviedb.org/3/movie/popular?api_key=${apiKey}`)
  if (!res.ok) throw new Error(`HTTP error ${res.status}`)
  const data = await res.json() as { results: Movie[] }
  return data.results
}
